begin;
create temporary table economy_fixture(k text primary key,id uuid default gen_random_uuid());
insert into economy_fixture(k)values('host'),('guest'),('sender'),('outsider'),('channel'),('live'),('gift'),('call'),('chat');
grant select on economy_fixture to authenticated,service_role;
insert into auth.users(id,aud,role,email,email_confirmed_at)select id,'authenticated','authenticated','economy-'||id||'@example.invalid',now()from economy_fixture where k in('host','guest','sender','outsider');
insert into public.pulse_channels(id,name,description,owner_id)select c.id,'Gift fixture','Test',h.id from economy_fixture c,economy_fixture h where c.k='channel' and h.k='host';
insert into public.pulse_live_sessions(id,channel_id,host_id,title)select l.id,c.id,h.id,'Gift fixture'from economy_fixture l,economy_fixture c,economy_fixture h where l.k='live'and c.k='channel'and h.k='host';
insert into pulse_private.live_guests(session_id,user_id,state)select l.id,g.id,'approved'from economy_fixture l,economy_fixture g where l.k='live'and g.k='guest';
insert into public.pulse_chats(id,kind,name,owner_id)select c.id,'direct','Call fixture',h.id from economy_fixture c,economy_fixture h where c.k='chat'and h.k='host';
insert into public.pulse_members(chat_id,user_id,role)select c.id,u.id,'member'from economy_fixture c,economy_fixture u where c.k='chat'and u.k in('host','sender');
update public.pulse_chat_requests set state='accepted' where chat_id=(select id from economy_fixture where k='chat');
insert into public.pulse_calls(id,chat_id,caller_id,kind)select c.id,t.id,h.id,'voice'from economy_fixture c,economy_fixture t,economy_fixture h where c.k='call'and t.k='chat'and h.k='host';
insert into public.pulse_call_members(call_id,user_id,state)select c.id,u.id,case when u.k='host'then'joined'else'ringing'end from economy_fixture c,economy_fixture u where c.k='call'and u.k in('host','sender');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='sender'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin
 if public.pulse_wallet()->>'coins'<>'0'then raise exception 'FAIL new wallet';end if;
 begin perform public.pulse_credit_coins(auth.uid(),'squad-live','forged',50,100);raise exception 'FAIL forged credit';exception when insufficient_privilege then null;end;
 begin perform 1 from pulse_private.wallets;raise exception 'FAIL private wallets';exception when insufficient_privilege then null;end;
 if not public.pulse_call_received((select id from economy_fixture where k='call'))then raise exception 'FAIL recipient ack';end if;
end $$;
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.pulse_credit_coins((select id from economy_fixture where k='sender'),'squad-live','test-fixture-receipt',50,100);
select public.pulse_credit_coins((select id from economy_fixture where k='sender'),'squad-live','test-fixture-receipt',50,100);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='sender'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_live_gifts('send',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='host'),'rose',1,(select id from economy_fixture where k='gift'));
select public.pulse_live_gifts('send',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='host'),'rose',1,(select id from economy_fixture where k='gift'));
do $$begin
 if public.pulse_wallet()->>'coins'<>'45'or public.pulse_wallet()->>'p_coins'<>'0'then raise exception 'FAIL duplicate debit or coins converted';end if;
 begin perform public.pulse_live_gifts('send',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='host'),'lion',1,gen_random_uuid());raise exception 'FAIL overspend';exception when others then if sqlerrm='FAIL overspend'then raise;end if;end;
 begin perform public.pulse_live_gifts('send',(select id from economy_fixture where k='live'),auth.uid(),'rose',1,gen_random_uuid());raise exception 'FAIL self gift';exception when others then if sqlerrm='FAIL self gift'then raise;end if;end;
 begin perform public.pulse_live_battle('invite',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='guest'));raise exception 'FAIL nonhost battle';exception when others then if sqlerrm='FAIL nonhost battle'then raise;end if;end;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='host'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if public.pulse_wallet()->>'p_coins'<>'2'or public.pulse_wallet()->>'coins'<>'0'then raise exception 'FAIL rose payout';end if;end $$;
select public.pulse_live_battle('invite',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='guest'));
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='guest'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_live_battle('accept',(select id from economy_fixture where k='live'));
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='sender'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_live_gifts('send',(select id from economy_fixture where k='live'),(select id from economy_fixture where k='guest'),'heart',1,gen_random_uuid());
do $$declare b jsonb;begin
 b=public.pulse_live_battle('info',(select id from economy_fixture where k='live'));
 if b->>'opponent_score'<>'10'or b->>'host_score'<>'0'then raise exception 'FAIL battle scoring';end if;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='outsider'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if public.pulse_call_received((select id from economy_fixture where k='call'))then raise exception 'FAIL outsider ack';end if;end $$;
reset role;
update public.pulse_calls set ring_deadline=now()-interval '1 second' where id=(select id from economy_fixture where k='call');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from economy_fixture where k='sender'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if public.pulse_call_received((select id from economy_fixture where k='call'))then raise exception 'FAIL expired ack';end if;end $$;
reset role;
rollback;
